#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-see-why-mail-was-refused. Do not edit.
set -e
cd "$(dirname "$0")"
cat > report.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Nightly report

All 42 jobs finished. None failed.
EOF
cat > why-refused.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh why-refused.sh LOG. Finds the last SMTP exchange in surl's -v log, waits (at most
# 10 s) until surl has ended it, then prints each refusal in it, a reply of 4xx or 5xx, with
# the two lines before it: the command and surl's reason.
log=$1
n=$(grep 'opened: smtp' "$log" | tail -n 1 | sed 's/^#\([0-9]*\) .*/\1/')
tries=0
until grep -q "^#$n \* Exchange $n ended" "$log"; do
  tries=$((tries + 1))
  if [ "$tries" -gt 10 ]; then echo "exchange $n has not ended" >&2; exit 1; fi
  sleep 1
done
grep -B 2 -E "^#$n > [45][0-9][0-9] " "$log" | grep "^#$n " | sed -e 's/^#[0-9]* //' -e 's/\\r\\n$//'
EOF
surl -v --log-file mail.log --mail-domain example.com --mailbox ann@example.com:annpass --mailbox "ops@example.com:opspass;quota=200" --mailbox app@example.com:apppass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
sh why-refused.sh mail.log
kill $(jobs -p)
